def close(self):
    if not self.active:
        return
    self.active = False
    subscribers = self.bus._subscriptions.get(self.topic)
    if subscribers is not None and self in subscribers:
        subscribers.remove(self)

def publish(self, event):
    for item in list(self._subscriptions.get(event["topic"], [])):
        if not item.active:
            continue
        if item.once:
            item.close()
        item.callback(event)

